import { DatabaseSync } from 'node:sqlite';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
function main(): void {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sqlite-compat-'));
  const file = path.join(dir, 'data.db');
  const db = new DatabaseSync(file);
  db.exec("CREATE TABLE k (v TEXT); INSERT INTO k VALUES ('one')");
  console.log(String(db.location()) === file, db.isOpen);
  db.close();
  const ro = new DatabaseSync(file, { readOnly: true });
  console.log((ro.prepare('SELECT v FROM k').get() as any).v);
  try { ro.exec("INSERT INTO k VALUES ('two')"); } catch (e: any) { console.log(e.code, e.errcode, e.errstr); }
  ro.close();
  fs.rmSync(dir, { recursive: true, force: true });
}
